  function setSiteState(customerId,siteId,state){const site=findSite(customerId,siteId);if(site){site.stato=state;saveDb();}}
  function deleteCustomer(id){if(!confirm('Rimuovere questo cliente, i suoi cantieri e interni dall’anagrafica? I rapportini già registrati resteranno nello storico.'))return;db.clienti=db.clienti.filter(c=>c.id!==id);saveDb();}
