  function calcGeneral(){const length=$('general-kind').value==='max-length',a=parseUtilityNumber('general-a'),b=parseUtilityNumber('general-b'),rho=generalCopper?.0175:.028;let answer;if(length){const voltage=parseUtilityNumber('general-voltage'),current=parseUtilityNumber('general-current'),allowed=voltage*b/100;answer=voltage>0&&current>0&&allowed>0&&a>0?allowed*a/((calcThreePhase?Math.sqrt(3):2)*rho*current*.9):NaN;}else{const pf=parseUtilityNumber('power-factor');answer=a>0&&b>0&&pf>0&&pf<=1?a*1000/((calcThreePhase?Math.sqrt(3):1)*b*pf):NaN;}$('general-result').textContent=Number.isFinite(answer)?`Risultato: ${fmt(answer,3)}${length?' m':' A'}`:'Controlla i valori inseriti.';}
