  function convertValue(){const value=parseUtilityNumber('conversion-value');if(!Number.isFinite(value)){$('conversion-result').textContent='Inserisci un valore valido.';return;}const kind=$('conversion-kind').value,rev=conversionReverse;let output,label;if(kind==='area'){if(value<=0){$('conversion-result').textContent='La sezione o il valore AWG deve essere valido.';return;}if(!rev){const d=Math.sqrt(4*value/Math.PI),awg=36-39*Math.log10(d/0.127)/Math.log10(92);output=Math.round(awg);label=`${fmt(value)} mm² ≈ AWG ${output} (controlla la misura commerciale)`;}else{const d=.127*Math.pow(92,(36-value)/39);output=Math.PI*d*d/4;label=`AWG ${fmt(value)} ≈ ${fmt(output,3)} mm²`;}}else if(kind==='length'){output=rev?value/3.28084:value*3.28084;label=rev?`${fmt(value)} ft = ${fmt(output)} m`:`${fmt(value)} m = ${fmt(output)} ft`;}else if(kind==='voltage'){output=rev?value/Math.sqrt(2):value*Math.sqrt(2);label=rev?`${fmt(value)} V di picco = ${fmt(output)} V efficaci`:`${fmt(value)} V efficaci = ${fmt(output)} V di picco`;}else if(kind==='power'){output=rev?value/1.35962:value*1.35962;label=rev?`${fmt(value)} CV = ${fmt(output)} kW`:`${fmt(value)} kW = ${fmt(output)} CV`;}else{output=rev?(value-32)*5/9:value*9/5+32;label=rev?`${fmt(value)} °F = ${fmt(output)} °C`:`${fmt(value)} °C = ${fmt(output)} °F`;}$('conversion-result').textContent=label;}
